INSERT INTO ayah_theme_chunks (source_chunk_id, surah_id, ayah_from, ayah_to, ayah_id_from, ayah_id_to, verse_key_from, verse_key_to, verses_count, theme, theme_bm, keywords, book_id) VALUES
(NULL, 1, 1, 7, (SELECT id FROM ayat WHERE surah_id = 1 AND ayah_number = 1), (SELECT id FROM ayat WHERE surah_id = 1 AND ayah_number = 7), '1:1', '1:7', 7, 'Supplication to Allah for guidance taught by Allah Himself', 'Doa memohon petunjuk kepada Allah yang diajar oleh Allah sendiri', ARRAY['Supplic', 'Allah'], 62),
(NULL, 2, 1, 5, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 1), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 5), '2:1', '2:5', 5, 'Claim of Al-Quran that there it contains no doubtful statement and Al-Quran is a guide for those who are God-conscious', 'Al-Quran mendakwa tiada keraguan di dalamnya dan ia adalah petunjuk bagi orang yang bertakwa', ARRAY[]::TEXT[], 62),
(NULL, 2, 6, 7, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 6), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 7), '2:6', '2:7', 2, 'Warning is of no use for those who reject faith', 'Peringatan tidak berguna bagi mereka yang menolak iman', ARRAY[]::TEXT[], 62),
(NULL, 2, 8, 16, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 8), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 16), '2:8', '2:16', 9, 'Hypocrites and the consequences of hypocrisy', 'Munafik dan akibat kemunafikan', ARRAY[]::TEXT[], 62),
(NULL, 2, 17, 20, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 17), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 20), '2:17', '2:20', 4, 'Examples of hypocrite''s deeds', 'Contoh perbuatan munafik', ARRAY[]::TEXT[], 62),
(NULL, 2, 21, 22, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 21), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 22), '2:21', '2:22', 2, 'Allah''s demand to worship Him', 'Perintah Allah untuk menyembah-Nya', ARRAY['Allah'], 62),
(NULL, 2, 23, 24, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 23), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 24), '2:23', '2:24', 2, 'Claim of Al-Quran to be the Book of Allah', 'Al-Quran mendakwa sebagai Kitab Allah', ARRAY['Allah'], 62),
(NULL, 2, 25, 25, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 25), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 25), '2:25', '2:25', 1, 'Reward for the believers', 'Ganjaran bagi orang beriman', ARRAY[]::TEXT[], 62),
(NULL, 2, 26, 27, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 26), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 27), '2:26', '2:27', 2, 'Parable of gnat may confound many and enlighten many', 'Perumpamaan nyamuk yang boleh mengelirukan dan menerangkan ramai', ARRAY['Parabl'], 62),
(NULL, 2, 28, 29, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 28), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 29), '2:28', '2:29', 2, 'How can you deny Allah?', 'Bagaimana kamu boleh menafikan Allah?', ARRAY['Allah'], 62),
(NULL, 2, 30, 30, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 30), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 30), '2:30', '2:30', 1, 'The story of Adam''s creation', 'Kisah penciptaan Adam', ARRAY['Adam'], 62),
(NULL, 2, 31, 33, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 31), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 33), '2:31', '2:33', 3, 'Victory of knowledge', 'Kemenangan ilmu', ARRAY[]::TEXT[], 62),
(NULL, 2, 34, 35, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 34), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 35), '2:34', '2:35', 2, 'Angels show respect to Adam', 'Malaikat menunjukkan hormat kepada Adam', ARRAY['Angel', 'Adam'], 62),
(NULL, 2, 36, 36, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 36), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 36), '2:36', '2:36', 1, 'Shaitan caused Adam to lose paradise', 'Syaitan menyebabkan Adam kehilangan syurga', ARRAY['Shaitan', 'Adam'], 62),
(NULL, 2, 37, 37, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 37), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 37), '2:37', '2:37', 1, 'Adam''s repentance and his forgiveness', 'Taubat Adam dan keampunan-Nya', ARRAY['Adam'], 62),
(NULL, 2, 38, 39, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 38), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 39), '2:38', '2:39', 2, 'Need of Allah''s revelations for guidance', 'Perlunya wahyu Allah untuk petunjuk', ARRAY['Allah'], 62),
(NULL, 2, 40, 43, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 40), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 43), '2:40', '2:43', 4, 'Allah''s covenants with the Children of Israel', 'Perjanjian Allah dengan Bani Israil', ARRAY['Allah', 'Children', 'Israel'], 62),
(NULL, 2, 44, 44, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 44), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 44), '2:44', '2:44', 1, 'Do you advise others and forget yourselves?', 'Adakah kamu menasihati orang lain tetapi lupa diri sendiri?', ARRAY['Do'], 62),
(NULL, 2, 45, 46, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 45), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 46), '2:45', '2:46', 2, 'Allah''s help come with patience and Salah', 'Pertolongan Allah datang dengan sabar dan solat', ARRAY['Allah', 'Salah'], 62),
(NULL, 2, 47, 48, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 47), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 48), '2:47', '2:48', 2, 'Criminals will find no way out on the Day of Judgement', 'Penjenayah tiada jalan keluar pada Hari Kiamat', ARRAY['Dai', 'Judgement'], 62),
(NULL, 2, 49, 50, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 49), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 50), '2:49', '2:50', 2, 'Israelites deliverance from Pharaoh''s persecution', 'Pembebasan Bani Israil dari penindasan Firaun', ARRAY['Israelit', 'Pharaoh'], 62),
(NULL, 2, 51, 52, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 51), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 52), '2:51', '2:52', 2, 'Their sin of worshipping the Calf', 'Dosa mereka menyembah anak lembu', ARRAY['Calf'], 62),
(NULL, 2, 53, 54, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 53), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 54), '2:53', '2:54', 2, 'Their repentance through slaying the culprits', 'Taubat mereka dengan membunuh pelaku', ARRAY[]::TEXT[], 62),
(NULL, 2, 55, 57, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 55), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 57), '2:55', '2:57', 3, 'Those who wanted to see Allah face to face were put to death, then Allah gave them life again and provided them with heavenly food', 'Orang yang mahu melihat Allah mati, kemudian dihidupkan semula dan diberi makanan syurga', ARRAY['Allah'], 62),
(NULL, 2, 58, 59, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 58), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 59), '2:58', '2:59', 2, 'Their discontent and disbelief', 'Ketamakan dan kekufuran mereka', ARRAY[]::TEXT[], 62),
(NULL, 2, 60, 60, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 60), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 60), '2:60', '2:60', 1, 'Miracle of providing water in the desert from a rock', 'Mukjizat menyediakan air di padang pasir dari batu', ARRAY[]::TEXT[], 62),
(NULL, 2, 61, 61, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 61), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 61), '2:61', '2:61', 1, 'Israelites rejected the heavenly food and their disobedience and transgression', 'Bani Israil menolak makanan syurga dan derhaka', ARRAY['Israelit'], 62),
(NULL, 2, 62, 62, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 62), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 62), '2:62', '2:62', 1, 'Real believers have nothing to fear or to regret', 'Orang beriman sebenar tiada takut atau menyesal', ARRAY['Real'], 62),
(NULL, 2, 63, 64, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 63), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 64), '2:63', '2:64', 2, 'Israelites covenant with Allah', 'Perjanjian Bani Israil dengan Allah', ARRAY['Israelit', 'Allah'], 62),
(NULL, 2, 65, 66, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 65), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 66), '2:65', '2:66', 2, 'Punishment for the violation of Sabbath', 'Hukuman melanggar hari Sabat', ARRAY['Sabbath'], 62),
(NULL, 2, 67, 71, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 67), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 71), '2:67', '2:71', 5, 'Their attitude in sacrificing a cow on Allah''s command', 'Sikap mereka dalam menyembelih lembu atas perintah Allah', ARRAY['Allah'], 62),
(NULL, 2, 72, 74, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 72), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 74), '2:72', '2:74', 3, 'Miracle of putting the dead body alive and their reaction to the miracle', 'Mukjizat menghidupkan mayat dan reaksi mereka', ARRAY[]::TEXT[], 62),
(NULL, 2, 75, 77, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 75), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 77), '2:75', '2:77', 3, 'Jews are hopeless victims of hypocrisy', 'Orang Yahudi adalah mangsa munafik yang putus asa', ARRAY[]::TEXT[], 62),
(NULL, 2, 78, 79, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 78), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 79), '2:78', '2:79', 2, 'Some of them attributed their own writings to Allah', 'Sebahagian mereka mengaitkan tulisan sendiri kepada Allah', ARRAY['Allah'], 62),
(NULL, 2, 80, 82, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 80), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 82), '2:80', '2:82', 3, 'Their false claim and its punishment', 'Tuntutan palsu mereka dan hukuman', ARRAY[]::TEXT[], 62),
(NULL, 2, 83, 83, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 83), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 83), '2:83', '2:83', 1, 'Israelites made a covenant with Allah and broke it', 'Bani Israil membuat perjanjian dengan Allah tetapi mereka memungkiri perjanjian itu.', ARRAY['Israelit', 'Allah'], 62),
(NULL, 2, 84, 86, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 84), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 86), '2:84', '2:86', 3, 'Their behavior with their own people and their punishment for breaking the covenant', 'Perilaku mereka terhadap kaum sendiri dan hukuman kerana memungkiri perjanjian.', ARRAY[]::TEXT[], 62),
(NULL, 2, 87, 88, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 87), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 88), '2:87', '2:88', 2, 'Advent of the Prophet Isa (Jesus)', 'Kedatangan Nabi Isa (Yesus).', ARRAY['Advent', 'Prophet', 'Isa', 'Jesu'], 62),
(NULL, 2, 89, 90, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 89), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 90), '2:89', '2:90', 2, 'Jews rejected the truth knowingly', 'Orang Yahudi menolak kebenaran dengan sengaja.', ARRAY[]::TEXT[], 62),
(NULL, 2, 91, 92, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 91), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 92), '2:91', '2:92', 2, 'Nature of the Jews'' belief', 'Sifat kepercayaan orang Yahudi.', ARRAY['Natur'], 62),
(NULL, 2, 93, 93, (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 93), (SELECT id FROM ayat WHERE surah_id = 2 AND ayah_number = 93), '2:93', '2:93', 1, 'Israelites love for the calf was more than their love for Allah', 'Kasih Bani Israil terhadap anak lembu lebih daripada kasih mereka kepada Allah.', ARRAY['Israelit', 'Allah'], 62),
