(NULL, 21, 16, 18, (SELECT id FROM ayat WHERE surah_id = 21 AND ayah_number = 16), (SELECT id FROM ayat WHERE surah_id = 21 AND ayah_number = 18), '21:16', '21:18', 3, 'The creation of heavens and earth is not a game', 'Penciptaan langit dan bumi bukanlah permainan.', ARRAY[]::TEXT[], 62),
